        GoRoute(
          path: AppRoutes.paywall,
          // Mirror the app router: the limit card shows only when the gate
          // named its reason (`?reason=limit`).
          builder: (context, state) =>
              PaywallScreen(showLimit: PaywallScreen.showLimitFor(state)),
